  </ZoomViewport>
  <div class="source-edit-actions"><button v-if="pen.length" :disabled="busy||pen.length<3||!!penError" @click="closePen">{{operationMode==='add'?(zh?'闭合添加路径':localize('Close additive path')):(zh?'闭合减去路径':localize('Close subtractive path'))}}</button><button v-if="pen.length" :disabled="busy" @click="pen.pop()">{{zh?'撤回路径点':localize('Undo path point')}}</button><button :disabled="busy||!history.canUndo.value" :aria-label="zh?'撤销花纹修改':localize('Undo marking edit')" @click="history.move()"><ToolIcon name="undo"/>{{zh?'撤销':localize('Undo')}}</button><button :disabled="busy||!history.canRedo.value" :aria-label="zh?'重做花纹修改':localize('Redo marking edit')" @click="history.move(true)"><ToolIcon name="redo"/></button><button v-if="selectedPoint" :disabled="!canNodes" @click="curve">{{draft.curves?.some(c=>c.startNodeId===selectedNode)?(zh?'改为直线':localize('Make straight')):(zh?'改为贝塞尔曲线':localize('Make Bézier curve'))}}</button><button v-if="selectedPoint" :disabled="!canNodes" @click="remove">{{zh?'删除选中源节点':localize('Delete selected source node')}}</button><span class="action-spacer"/><button :disabled="busy||!dirty" @click="reset">{{zh?'取消源花纹编辑':localize('Cancel source marking edit')}}</button><button class="primary" :disabled="!canConfirm" @click="confirm">{{zh?'保存花纹修改':localize('Save marking changes')}}</button></div>
  <p class="source-edit-help">{{tool==='select'?(zh?'虚线内是当前花纹选区。用「增加选区」补全缺失部分，用「减少选区」去掉多余区域。':localize('The dotted boundary is the current selection. Use Add selection to paint missing areas, or Subtract selection to remove unwanted areas.')):tool==='node'?(zh?'拖动节点或方形曲线手柄。Ctrl 点击轮廓插点；Delete 删除选中节点。Shift 拖动移动花纹。':localize('Drag nodes or square curve handles. Ctrl-click inserts; Delete removes the selected node. Shift-drag moves the contour.')):tool==='brush-erase'?(zh?'减少选区模式：按住拖动，从当前选区减去涂过的区域。保存后更新同一花纹，不会擦除原图。':localize('Subtract selection: drag to remove painted areas from the selection. Saving updates the same marking; the original image is unchanged.')):tool==='brush-add'?(zh?'增加选区模式：按住拖动，将缺失部分加入当前选区。保存后更新同一花纹。':localize('Add selection: drag to paint missing areas into the selection. Saving updates the same marking.')):tool.startsWith('pen')?(zh?'点击绘制路径，闭合后按当前工具增加或减去选区。':localize('Click to draw a path, then close it to add to or subtract from the selection.')):(zh?'拖动平移视图。':localize('Drag to pan the view.'))}} {{zh?'中键 / 空格拖动平移，滚轮缩放。':localize('Middle/Space drag pans; wheel zooms.')}}</p>
  <p v-if="message||error||penError||stale||saveMessage" class="source-edit-message" role="status">{{saveMessage|| (stale?(zh?'源花纹已更新；取消草稿后重新编辑。':localize('The source changed; cancel this draft and reload.')):(message||(error||penError?(zh?'轮廓有交叉或重合，请调整节点后确认。':localize('Contour crosses or overlaps; repair the nodes before confirming.')) :'')))}}</p>
 </section>
</template>

<script setup lang="ts">
import EmbeddedImage from './EmbeddedImage.vue';
import {localize} from './localization';

import {computed,ref,shallowRef,useTemplateRef,watch,onMounted,onBeforeUnmount} from 'vue';
