function down(event:PointerEvent){svg.value?.focus({preventScroll:true});if(event.button!==0||interaction.value==='pan'||props.busy)return;const p=point(event);if(!p)return;if(tool.value==='select')return;if(tool.value==='node'){selectedNode.value='';if(!canNodes.value)return;if(event.ctrlKey||event.metaKey){try{const next=insertSourceNode(draft.value,p);draft.value=next.piece;selectedNode.value=next.nodeId;}catch(e){message.value=(e as Error).message;}return;}if(event.shiftKey){gesture={kind:'translate',start:p,original:cloneSource(draft.value)};capture(event);}return;}
 if(tool.value.startsWith('brush')){if(!Number.isFinite(radius.value)||radius.value<.1||radius.value>200){message.value=zh.value?'笔刷半径须为 0.1–200 mm。':localize('Brush radius must be 0.1–200 mm.');return;}if(operations.value.length>=50){message.value=zh.value?'笔画过多，请先确认。':localize('Confirm these strokes before drawing more.');return;}capture(event);stroke.value=[p];gesture={kind:'brush'};return;}
 if(tool.value.startsWith('pen')){if(pen.value.length>=2000){message.value=zh.value?'路径最多 2000 个节点。':localize('At most 2000 path nodes.');return;}pen.value.push(p);selectedPen.value=pen.value.length-1;}
}
function move(event:PointerEvent){const p=point(event);hover.value=p;if(!gesture||props.busy||!p)return;if(gesture.kind==='pen')pen.value[gesture.index]=p;else if(gesture.kind==='node')draft.value=moveNode(draft.value,gesture.id,p.xMm,p.yMm);else if(gesture.kind==='handle'){const {curveId,handle}=gesture;draft.value={...draft.value,curves:draft.value.curves?.map(c=>c.id===curveId?{...c,[handle]:{...c[handle],...p}}:c)};}else if(gesture.kind==='translate'){const {start,original}=gesture;draft.value=mapPiece(original,n=>({xMm:n.xMm+p.xMm-start.xMm,yMm:n.yMm+p.yMm-start.yMm}));}else{const last=stroke.value.at(-1)!;if(Math.hypot(p.xMm-last.xMm,p.yMm-last.yMm)>=Math.max(.05,radius.value/8)){if(stroke.value.length>=500){history.rollback();stroke.value=[];gesture=undefined;message.value=zh.value?'这一笔过长，已取消；请分成较短笔画。':localize('Stroke too long; cancelled. Draw shorter strokes.');}else stroke.value.push(p);}}}
function finish(event:PointerEvent){if(!gesture)return;if(event.type==='pointercancel'){cancelGesture();return;}if(gesture.kind==='brush'&&stroke.value.length)operations.value.push({kind:'brush',mode:operationMode.value,radiusMm:radius.value,points:stroke.value.map(p=>({...p}))});stroke.value=[];gesture=undefined;history.end();if(svg.value?.hasPointerCapture(event.pointerId))svg.value.releasePointerCapture(event.pointerId);}
function cancelGesture(){if(!gesture)return;history.rollback();gesture=undefined;stroke.value=[];}
watch(()=>props.active,value=>{if(value===false)cancelGesture();});
function closePen(){if(pen.value.length<3||penError.value||operations.value.length>=50)return;history.begin();operations.value.push({kind:'pen',mode:operationMode.value,points:pen.value.map(p=>({...p}))});pen.value=[];selectedPen.value=-1;history.end();}
function remove(){if(!selectedNode.value||!canNodes.value)return;const ring=[draft.value.nodes,...(draft.value.holes??[])].find(r=>r.some(n=>n.id===selectedNode.value));if(ring&&ring.length<=3){message.value=zh.value?'闭合轮廓至少保留 3 个节点。':localize('A closed contour needs at least 3 nodes.');return;}draft.value=removeSourceNode(draft.value,selectedNode.value);selectedNode.value='';}
function curve(){const p=selectedPoint.value;if(!p||!canNodes.value||!draft.value.nodes.some(n=>n.id===p.id))return;const i=draft.value.nodes.findIndex(n=>n.id===p.id),b=draft.value.nodes[(i+1)%draft.value.nodes.length],existing=draft.value.curves?.find(c=>c.startNodeId===p.id),curves=draft.value.curves?.filter(c=>c.startNodeId!==p.id)??[];if(!existing)curves.push({id:crypto.randomUUID(),startNodeId:p.id,endNodeId:b.id,c1:{id:crypto.randomUUID(),xMm:p.xMm+(b.xMm-p.xMm)/3,yMm:p.yMm+(b.yMm-p.yMm)/3},c2:{id:crypto.randomUUID(),xMm:p.xMm+2*(b.xMm-p.xMm)/3,yMm:p.yMm+2*(b.yMm-p.yMm)/3}});draft.value={...draft.value,curves};}
function key(event:KeyboardEvent){if(event.target instanceof Element&&event.target.closest('input,textarea,select,[contenteditable=true]'))return;if((event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase()))return;if(['Delete','Backspace'].includes(event.key)){event.preventDefault();event.stopPropagation();if(pen.value.length){if(selectedPen.value>=0)pen.value.splice(selectedPen.value,1);else pen.value.pop();selectedPen.value=-1;}else remove();}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(pen.value.length){pen.value=[];return;}if(gesture){history.rollback();stroke.value=[];gesture=undefined;return;}selectedNode.value='';}}
function getEdit():SourceEdit|undefined{if(!canConfirm.value)return;return {piece:cloneSource(draft.value),operations:JSON.parse(JSON.stringify(operations.value)) as SourceOperation[]};}
function confirm(){const edit=getEdit();if(edit)emit('commit',edit);}
function toggleNodes(){useTool(nodesEnabled.value?'node':'select');}
function selectionUnit(box:string){return handleRadius(box)/5;}
defineExpose({getEdit,reset,dirty,canConfirm});
onMounted(()=>{observer=new ResizeObserver(entries=>{const r=entries[0]?.contentRect;if(r)size.value={width:r.width,height:r.height};});if(svg.value)observer.observe(svg.value);});onMounted(()=>window.addEventListener('blur',cancelGesture));onBeforeUnmount(()=>{window.removeEventListener('blur',cancelGesture);observer?.disconnect();});
</script>

